/**
 * Mirrors of the CPython exception objects that the original program can
 * surface to the terminal.
 *
 * Only the pieces observable from the outside are modelled: the exception type
 * name (printed as the last traceback line's prefix), the message, and the
 * Python call frames that led to the raise.
 */

export class PythonError extends Error {
  /**
   * @param {string} pythonType exception class name as CPython prints it
   * @param {string} message    the exception's str()
   */
  constructor(pythonType, message) {
    super(message);
    this.name = pythonType;
    this.pythonType = pythonType;
    /** @type {{file: string, line: number, name: string}[]} outermost first */
    this.pyFrames = [];
  }
}

export class OverflowError extends PythonError {
  constructor(message) {
    super('OverflowError', message);
  }
}

export class ValueError extends PythonError {
  constructor(message) {
    super('ValueError', message);
  }
}

/** schedule's own error hierarchy: ScheduleError -> ScheduleValueError. */
export class ScheduleError extends PythonError {
  constructor(message, pythonType = 'ScheduleError') {
    super(pythonType, message);
  }
}

export class ScheduleValueError extends ScheduleError {
  constructor(message) {
    super(message, 'ScheduleValueError');
  }
}

/**
 * argparse aborts by raising SystemExit; we carry the status code so the entry
 * point can translate it into a process exit status.
 */
export class SystemExit extends PythonError {
  constructor(code) {
    super('SystemExit', String(code));
    this.code = code;
  }
}

