/**
 * The two Unicode predicates CPython leans on when it turns a string into an
 * int, plus the one it needs for repr().
 *
 * Node ships Unicode property escapes, so the tables are derived at runtime
 * instead of being transcribed by hand.
 */

/**
 * Code points for which CPython's Py_UNICODE_ISSPACE() is true.
 *
 * Deliberately not JS's `\s`: CPython counts the C0 separators U+001C..U+001F
 * and U+0085 as space, and does *not* count U+FEFF (a format character, not a
 * separator).
 */
const PY_WHITESPACE = new Set([
  0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1c, 0x1d, 0x1e, 0x1f, 0x20, 0x85, 0xa0,
  0x1680, 0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005, 0x2006, 0x2007,
  0x2008, 0x2009, 0x200a, 0x2028, 0x2029, 0x202f, 0x205f, 0x3000,
]);

export function isPythonWhitespace(codePoint) {
  return PY_WHITESPACE.has(codePoint);
}

/** Highest code point that carries General_Category=Nd in any Unicode release. */
const ND_SCAN_LIMIT = 0x1ffff;
const ND_RE = /\p{Nd}/u;

/** @type {{start: number, end: number}[] | null} */
let ndRuns = null;

/**
 * Maximal runs of consecutive Nd code points.
 *
 * Every decimal-digit block is exactly ten code points wide and blocks are
 * laid out back to back inside a run (U+1D7CE..U+1D7FF packs five of them), so
 * a digit's value is its offset within the run, modulo ten. That holds for
 * every run and needs no per-block table.
 */
function decimalRuns() {
  if (ndRuns !== null) return ndRuns;
  const runs = [];
  let start = -1;
  for (let cp = 0; cp <= ND_SCAN_LIMIT; cp += 1) {
    if (ND_RE.test(String.fromCodePoint(cp))) {
      if (start < 0) start = cp;
    } else if (start >= 0) {
      runs.push({ start, end: cp - 1 });
      start = -1;
    }
  }
  if (start >= 0) runs.push({ start, end: ND_SCAN_LIMIT });
  ndRuns = runs;
  return runs;
}

/**
 * Decimal value of a code point, or -1 when it is not a decimal digit.
 * ASCII takes a fast path so the Unicode scan only happens for exotic input.
 */
export function decimalDigitValue(codePoint) {
  if (codePoint >= 0x30 && codePoint <= 0x39) return codePoint - 0x30;
  if (codePoint < 0x80 || codePoint > ND_SCAN_LIMIT) return -1;
  for (const run of decimalRuns()) {
    if (codePoint >= run.start && codePoint <= run.end) {
      return (codePoint - run.start) % 10;
    }
  }
  return -1;
}

/**
 * str.isprintable() for a single character: everything except the separator
 * and "other" categories, with U+0020 carved out as printable.
 */
const NON_PRINTABLE_RE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

export function isPrintable(character) {
  if (character === ' ') return true;
  return !NON_PRINTABLE_RE.test(character);
}

