/**
 * repr() for the handful of value shapes this program can print: strings
 * (argparse quotes the offending value with %r), integers, tuples and dicts.
 */

import { isPrintable } from './unicode.mjs';

/**
 * CPython's unicode_repr(): prefer single quotes, switch to double quotes when
 * the text contains a single quote but no double quote, and escape only
 * backslash, the active quote, \t, \n, \r and non-printable code points.
 */
export function reprString(value) {
  let hasSingle = false;
  let hasDouble = false;
  for (const character of value) {
    if (character === "'") hasSingle = true;
    else if (character === '"') hasDouble = true;
  }
  const quote = hasSingle && !hasDouble ? '"' : "'";

  let out = quote;
  for (const character of value) {
    if (character === quote || character === '\\') {
      out += `\\${character}`;
    } else if (character === '\t') {
      out += '\\t';
    } else if (character === '\n') {
      out += '\\n';
    } else if (character === '\r') {
      out += '\\r';
    } else if (isPrintable(character)) {
      out += character;
    } else {
      const codePoint = character.codePointAt(0);
      if (codePoint < 0x100) {
        out += `\\x${codePoint.toString(16).padStart(2, '0')}`;
      } else if (codePoint < 0x10000) {
        out += `\\u${codePoint.toString(16).padStart(4, '0')}`;
      } else {
        out += `\\U${codePoint.toString(16).padStart(8, '0')}`;
      }
    }
  }
  return out + quote;
}

/** Python ints are unbounded, so they are carried as BigInt and printed bare. */
export function reprInt(value) {
  return typeof value === 'bigint' ? value.toString() : String(value);
}

export function reprValue(value) {
  if (typeof value === 'bigint' || typeof value === 'number') return reprInt(value);
  if (typeof value === 'string') return reprString(value);
  if (value === null || value === undefined) return 'None';
  if (value === true) return 'True';
  if (value === false) return 'False';
  if (Array.isArray(value)) return reprTuple(value);
  return reprDict(value);
}

/** `()`, `(1,)`, `(1, 2)` — note the trailing comma for one-element tuples. */
export function reprTuple(items) {
  if (items.length === 0) return '()';
  if (items.length === 1) return `(${reprValue(items[0])},)`;
  return `(${items.map(reprValue).join(', ')})`;
}

/** `{}` or `{'key': value}` in insertion order. */
export function reprDict(mapping) {
  const entries = mapping instanceof Map ? [...mapping.entries()] : Object.entries(mapping);
  if (entries.length === 0) return '{}';
  return `{${entries.map(([k, v]) => `${reprString(k)}: ${reprValue(v)}`).join(', ')}}`;
}

