/**
 * int(str) with CPython's exact acceptance grammar, returning a BigInt so that
 * arbitrarily large literals survive intact.
 *
 * CPython first runs _PyUnicode_TransformDecimalAndSpaceToASCII over the text
 * (any Unicode decimal digit becomes its ASCII counterpart, any Unicode space
 * becomes U+0020) and only then applies PyLong_FromString. Doing it in the same
 * two steps is what makes '٤٢', '１_０' and '5 ' behave the way they do.
 */

import { ValueError } from './errors.mjs';
import { decimalDigitValue, isPythonWhitespace } from './unicode.mjs';
import { reprString } from './repr.mjs';

/** Digits, optionally separated by single underscores, with an optional sign. */
const INT_LITERAL_RE = /^ *([+-]?)([0-9](?:_?[0-9])*) *$/;

function transformDecimalAndSpaceToAscii(text) {
  let out = '';
  for (const character of text) {
    const codePoint = character.codePointAt(0);
    const digit = decimalDigitValue(codePoint);
    if (digit >= 0) {
      out += String(digit);
    } else if (isPythonWhitespace(codePoint)) {
      out += ' ';
    } else {
      out += character;
    }
  }
  return out;
}

/**
 * @param {string} text
 * @returns {bigint}
 * @throws {ValueError} with CPython's "invalid literal for int() with base 10" text
 */
export function pyInt(text) {
  const match = INT_LITERAL_RE.exec(transformDecimalAndSpaceToAscii(text));
  if (match === null) {
    throw new ValueError(
      `invalid literal for int() with base 10: ${reprString(text)}`,
    );
  }
  const [, sign, digits] = match;
  const magnitude = BigInt(digits.replace(/_/g, ''));
  return sign === '-' ? -magnitude : magnitude;
}

