/**
 * Enough of CPython's datetime module to reproduce schedule's arithmetic
 * exactly, including both ways it can overflow.
 *
 * A datetime is stored as a BigInt count of microseconds since
 * 0001-01-01 00:00:00, which makes range checks and comparisons trivial and
 * keeps every value exact regardless of magnitude.
 */

import { OverflowError } from './errors.mjs';

export const MICROSECONDS_PER_SECOND = 1_000_000n;
export const SECONDS_PER_DAY = 86_400n;
export const MICROSECONDS_PER_DAY = SECONDS_PER_DAY * MICROSECONDS_PER_SECOND;

/** timedelta rejects |days| > 999999999 ... */
const MAX_DELTA_DAYS = 999_999_999n;
/** ... but only after squeezing the day count into a C int. */
const C_INT_MAX = 2_147_483_647n;
const C_INT_MIN = -2_147_483_648n;

/** date(1970, 1, 1).toordinal() */
const UNIX_EPOCH_ORDINAL = 719_163n;
/** date(9999, 12, 31).toordinal() */
const MAX_ORDINAL = 3_652_059n;

/** datetime.min is 0001-01-01 00:00:00, i.e. microsecond zero. */
export const MIN_MICROSECONDS = 0n;
/** datetime.max is 9999-12-31 23:59:59.999999. */
export const MAX_MICROSECONDS =
  (MAX_ORDINAL - 1n) * MICROSECONDS_PER_DAY + MICROSECONDS_PER_DAY - 1n;

const MAX_WHOLE_SECONDS = Number(MAX_MICROSECONDS / MICROSECONDS_PER_SECOND);

/** Microseconds in one unit of each interval keyword timedelta() accepts. */
const UNIT_MICROSECONDS = {
  microseconds: 1n,
  milliseconds: 1_000n,
  seconds: MICROSECONDS_PER_SECOND,
  minutes: 60n * MICROSECONDS_PER_SECOND,
  hours: 3_600n * MICROSECONDS_PER_SECOND,
  days: MICROSECONDS_PER_DAY,
  weeks: 7n * MICROSECONDS_PER_DAY,
};

function floorDiv(a, b) {
  const quotient = a / b;
  return a % b !== 0n && a < 0n !== b < 0n ? quotient - 1n : quotient;
}

function floorMod(a, b) {
  return a - floorDiv(a, b) * b;
}

/** Days between 1970-01-01 and the given proleptic-Gregorian date. */
function daysFromCivil(year, month, day) {
  const y = BigInt(year) - (month <= 2 ? 1n : 0n);
  const era = floorDiv(y, 400n);
  const yearOfEra = y - era * 400n;
  const monthShift = BigInt(month) + (month > 2 ? -3n : 9n);
  const dayOfYear = (153n * monthShift + 2n) / 5n + BigInt(day) - 1n;
  const dayOfEra = yearOfEra * 365n + yearOfEra / 4n - yearOfEra / 100n + dayOfYear;
  return era * 146_097n + dayOfEra - 719_468n;
}

/**
 * A normalized timedelta.
 *
 * Construction mirrors microseconds_to_delta_ex(): the total is split into
 * (days, seconds, microseconds) with floor semantics, the day count is coerced
 * to a C int, and only then is its magnitude checked.
 */
export class TimeDelta {
  /** @param {bigint} totalMicroseconds */
  constructor(totalMicroseconds) {
    const totalSeconds = floorDiv(totalMicroseconds, MICROSECONDS_PER_SECOND);
    const microseconds = floorMod(totalMicroseconds, MICROSECONDS_PER_SECOND);
    const days = floorDiv(totalSeconds, SECONDS_PER_DAY);
    const seconds = floorMod(totalSeconds, SECONDS_PER_DAY);

    if (days > C_INT_MAX || days < C_INT_MIN) {
      throw new OverflowError('Python int too large to convert to C int');
    }
    if (days > MAX_DELTA_DAYS || days < -MAX_DELTA_DAYS) {
      throw new OverflowError(
        `days=${days}; must have magnitude <= ${MAX_DELTA_DAYS}`,
      );
    }

    this.days = days;
    this.seconds = seconds;
    this.microseconds = microseconds;
    this.totalMicroseconds = totalMicroseconds;
  }

  /**
   * timedelta(**{unit: interval}) for a single integer keyword.
   * @param {string} unit  one of the UNIT_MICROSECONDS keys
   * @param {bigint} interval
   */
  static fromUnit(unit, interval) {
    const scale = UNIT_MICROSECONDS[unit];
    if (scale === undefined) {
      throw new OverflowError(`unsupported timedelta unit: ${unit}`);
    }
    return new TimeDelta(interval * scale);
  }

  static fromDays(days) {
    return TimeDelta.fromUnit('days', BigInt(days));
  }

  subtract(other) {
    return new TimeDelta(this.totalMicroseconds - other.totalMicroseconds);
  }

  isZero() {
    return this.totalMicroseconds === 0n;
  }
}

/** A naive datetime, i.e. no tzinfo — which is all schedule uses by default. */
export class DateTime {
  /** @param {bigint} microseconds since 0001-01-01 00:00:00 */
  constructor(microseconds) {
    this.microseconds = microseconds;
  }

  /** datetime.datetime.now() — local wall clock, no timezone attached. */
  static now(clock = new Date()) {
    const ordinal =
      daysFromCivil(clock.getFullYear(), clock.getMonth() + 1, clock.getDate()) +
      UNIX_EPOCH_ORDINAL;
    const secondsOfDay =
      BigInt(clock.getHours()) * 3_600n +
      BigInt(clock.getMinutes()) * 60n +
      BigInt(clock.getSeconds());
    return new DateTime(
      (ordinal - 1n) * MICROSECONDS_PER_DAY +
        secondsOfDay * MICROSECONDS_PER_SECOND +
        BigInt(clock.getMilliseconds()) * 1_000n,
    );
  }

  /** datetime + timedelta, raising the same OverflowError CPython raises. */
  add(delta) {
    return new DateTime(checkedMicroseconds(this.microseconds + delta.totalMicroseconds));
  }

  /** Monday is 0, matching date.weekday(). */
  weekday() {
    const ordinal = floorDiv(this.microseconds, MICROSECONDS_PER_DAY) + 1n;
    return Number(floorMod(ordinal + 6n, 7n));
  }

  lessOrEqual(other) {
    return this.microseconds <= other.microseconds;
  }
}

function checkedMicroseconds(microseconds) {
  if (microseconds < MIN_MICROSECONDS || microseconds > MAX_MICROSECONDS) {
    throw new OverflowError('date value out of range');
  }
  return microseconds;
}

/**
 * `while next_run <= now: next_run += period`.
 *
 * A zero period never terminates — exactly like the original, which spins
 * forever when the interval is 0. A negative period walks backwards until the
 * datetime falls off 0001-01-01 and raises "date value out of range".
 *
 * @param {DateTime} start      the candidate next run
 * @param {DateTime} reference  the captured "now"
 * @param {TimeDelta} period
 * @returns {DateTime}
 */
export function advanceUntilAfter(start, reference, period) {
  const periodMicroseconds = period.totalMicroseconds;

