/**
 * Python call frames, recorded so an unhandled exception can be reported with
 * the same traceback the frozen program prints.
 *
 * Each raise site is wrapped by the frame it belongs to; because the innermost
 * wrapper runs first, unshifting keeps the list outermost-first, which is the
 * order CPython prints.
 */

import { PythonError } from './errors.mjs';

/**
 * @param {string} file  file name as it appears in the traceback
 * @param {number} line
 * @param {string} name  enclosing function, or '<module>' at top level
 * @param {() => T} body
 * @returns {T}
 * @template T
 */
export function pyFrame(file, line, name, body) {
  try {
    return body();
  } catch (error) {
    if (error instanceof PythonError) {
      error.pyFrames.unshift({ file, line, name });
    }
    throw error;
  }
}

