/**
 * Traceback rendering.
 *
 * The frozen build ships no .py sources, so PyInstaller's traceback shows the
 * "File ..., line N, in NAME" header for each frame with no source echo, and
 * the bootloader appends a failure line tagged with the process id.
 */

export function formatTraceback(error) {
  const lines = ['Traceback (most recent call last):'];
  for (const frame of error.pyFrames) {
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.name}`);
  }
  lines.push(
    error.message === '' ? error.pythonType : `${error.pythonType}: ${error.message}`,
  );
  return `${lines.join('\n')}\n`;
}

export function formatBootloaderFailure(scriptName, pid = process.pid) {
  return `[PYI-${pid}:ERROR] Failed to execute script '${scriptName}' due to unhandled exception!\n`;
}

