/**
 * The two functools pieces schedule relies on when it stores a job's callable:
 * functools.partial (which is what exposes .args and .kwargs to Job.__str__)
 * and functools.update_wrapper (which copies __name__ across, so a lambda keeps
 * printing as `<lambda>`).
 */

/** Tags a callable with the __name__ CPython gives an anonymous function. */
export function lambda(implementation) {
  implementation.__name__ = '<lambda>';
  return implementation;
}

/**
 * @param {Function} func
 * @param {unknown[]} args
 * @param {Record<string, unknown>} kwargs
 */
export function partial(func, args = [], kwargs = {}) {
  const bound = (...extra) => func(...args, ...extra);
  bound.func = func;
  bound.args = args;
  bound.kwargs = kwargs;
  return bound;
}

export function updateWrapper(wrapper, wrapped) {
  if (wrapped.__name__ !== undefined) wrapper.__name__ = wrapped.__name__;
  else if (wrapped.name) wrapper.__name__ = wrapped.name;
  return wrapper;
}

