/**
 * stdout/stderr with CPython's buffering behaviour.
 *
 * This matters for byte-exact parity: CPython line-buffers stdout when it is a
 * tty but block-buffers it when it is a pipe or file, flushing only as the
 * interpreter exits. So when the program dies mid-way with output redirected,
 * the traceback (stderr, unbuffered) lands *before* the numbers already
 * "printed", and output still sitting in the buffer when the process is killed
 * is lost entirely. Both effects are visible in the reference program.
 *
 * Every write goes through fs.writeSync so nothing can be dropped by an
 * asynchronous flush racing process.exit().
 */

import { writeSync } from 'node:fs';
import { pyStr } from '../python/repr.mjs';

const STDOUT_FD = 1;
const STDERR_FD = 2;

const stdoutIsLineBuffered = process.stdout.isTTY === true;
let bufferedStdout = '';

function writeToFd(fd, text) {
  if (text === '') return;
  const buffer = Buffer.from(text, 'utf8');
  let offset = 0;
  while (offset < buffer.length) {
    try {
      offset += writeSync(fd, buffer, offset, buffer.length - offset);
    } catch (error) {
      if (error.code === 'EAGAIN') continue;
      if (error.code === 'EPIPE') return;
      throw error;
    }
  }
}

/** print(*values) with Python's default sep=' ' and end='\n'. */
export function print(...values) {
  const text = `${values.map(pyStr).join(' ')}\n`;
  if (stdoutIsLineBuffered) writeToFd(STDOUT_FD, text);
  else bufferedStdout += text;
}

export function writeStdout(text) {
  if (stdoutIsLineBuffered) writeToFd(STDOUT_FD, text);
  else bufferedStdout += text;
}

/** stderr is unbuffered in CPython, so this always reaches the fd at once. */
export function writeStderr(text) {
  writeToFd(STDERR_FD, text);
}

export function flushStdout() {
  const pending = bufferedStdout;
  bufferedStdout = '';
  writeToFd(STDOUT_FD, pending);
}

/** Flush like the interpreter's exit hook does, then set the status code. */
export function exitProcess(code) {
  flushStdout();
  process.exit(code);
}

