/**
 * argparse's HelpFormatter: usage line, wrapping, and the two-column options
 * block.
 *
 * The reference program honours COLUMNS (argparse asks
 * shutil.get_terminal_size() for the width), so the wrapping algorithm is
 * reproduced rather than assumed away — at COLUMNS=30 the usage really does
 * break between `--c` and `C`, because argparse splits the usage into
 * whitespace-separated parts and greedily refills them.
 */

import { pyInt } from '../python/int.mjs';

/** shutil.get_terminal_size(): COLUMNS wins, then the tty, then 80. */
export function terminalColumns(env = process.env, stream = process.stdout) {
  let columns = 0;
  if (env.COLUMNS !== undefined) {
    try {
      columns = Number(pyInt(env.COLUMNS));
    } catch {
      columns = 0;
    }
  }
  if (columns <= 0) {
    columns = stream.isTTY && stream.columns > 0 ? stream.columns : 80;
  }
  return columns;
}

/** Greedy whitespace wrap; equivalent to textwrap.wrap() for help strings. */
function wrapText(text, width) {
  const words = text.split(/\s+/).filter((word) => word !== '');
  if (words.length === 0) return [];
  const lines = [];
  let line = words[0];
  for (const word of words.slice(1)) {
    if (line.length + 1 + word.length <= width) {
      line += ` ${word}`;
    } else {
      lines.push(line);
      line = word;
    }
  }
  lines.push(line);
  return lines;
}

/**
 * Splits a rendered usage string the way argparse's part_regexp does: bracketed
 * groups stay whole, everything else splits on whitespace.
 */
const PART_RE = /\(.*?\)+(?=\s|$)|\[.*?\]+(?=\s|$)|\S+/g;

export class HelpFormatter {
  constructor(prog, { width = terminalColumns() - 2, indentIncrement = 2 } = {}) {
    this.prog = prog;
    this.width = width;
    this.indentIncrement = indentIncrement;
    this.maxHelpPosition = Math.min(
      24,
      Math.max(this.width - 20, indentIncrement * 2),
    );
  }

