  formatUsage(actions) {
    const prefix = 'usage: ';
    const optionals = actions.filter((action) => action.optionStrings.length > 0);
    const positionals = actions.filter((action) => action.optionStrings.length === 0);
    const optUsage = this.formatActionsUsage(optionals);
    const posUsage = this.formatActionsUsage(positionals);
    let usage = [this.prog, optUsage, posUsage].filter((part) => part !== '').join(' ');

    const textWidth = this.width;
    if (prefix.length + usage.length > textWidth) {
      const optParts = optUsage.match(PART_RE) ?? [];
      const posParts = posUsage.match(PART_RE) ?? [];

      const getLines = (parts, indent, linePrefix = null) => {
        const lines = [];
        let line = [];
        let lineLen = (linePrefix === null ? indent.length : linePrefix.length) - 1;
        for (const part of parts) {
          if (lineLen + 1 + part.length > textWidth && line.length > 0) {
            lines.push(indent + line.join(' '));
            line = [];
            lineLen = indent.length - 1;
          }
          line.push(part);
          lineLen += 1 + part.length;
        }
        if (line.length > 0) lines.push(indent + line.join(' '));
        if (linePrefix !== null && lines.length > 0) {
