  }

  /** Collapse runs of blank lines and leave exactly one trailing newline. */
  static finish(text) {
    if (text === '') return text;
    return `${text.replace(/\n\n\n+/g, '\n\n').replace(/^\n+|\n+$/g, '')}\n`;
  }
}

