export function terminalColumns(env = process.env, stream = process.stdout) {
  let columns = 0;
  if (env.COLUMNS !== undefined) {
    try {
      columns = Number(pyInt(env.COLUMNS));
    } catch {
      columns = 0;
    }
  }
  if (columns <= 0) {
    columns = stream.isTTY && stream.columns > 0 ? stream.columns : 80;
  }
  return columns;
}

/** Greedy whitespace wrap; equivalent to textwrap.wrap() for help strings. */
function wrapText(text, width) {
  const words = text.split(/\s+/).filter((word) => word !== '');
  if (words.length === 0) return [];
