/**
 * The two argparse actions this program needs: `store` (the implicit default
 * for `add_argument`) and `help`.
 */

export class Action {
  constructor({
    optionStrings = [],
    dest,
    nargs = null,
    required = false,
    help = null,
    metavar = null,
    type = null,
    typeName = null,
    defaultValue = null,
  }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.nargs = nargs;
    this.required = required;
    this.help = help;
    this.metavar = metavar;
    this.type = type;
    this.typeName = typeName;
    this.defaultValue = defaultValue;
  }

  /** argparse defaults an optional's metavar to dest.upper(). */
  formatMetavar() {
    return this.metavar ?? this.dest.toUpperCase();
  }

  /** _get_action_name(): what error messages call this argument. */
  actionName() {
    if (this.optionStrings.length > 0) return this.optionStrings.join('/');
    return this.metavar ?? this.dest;
  }

  call() {
    throw new Error('Action.call must be overridden');
  }
}

export class StoreAction extends Action {
  call(parser, namespace, values) {
    namespace[this.dest] = values;
  }
}

export class HelpAction extends Action {
  constructor(options) {
    super({ ...options, nargs: 0, dest: options.dest ?? 'help' });
  }

  call(parser) {
    parser.printHelp();
    parser.exit(0);
  }
}

