/**
 * The slice of argparse.ArgumentParser this program exercises: long options
 * with a single value, `-h/--help`, `required=True`, `type=` conversion, option
 * abbreviation, and the four error templates.
 *
 * The parser the original builds declares no positional arguments, so any token
 * that is not an option or an option's value is a leftover and ends up in the
 * "unrecognized arguments" list. That is modelled directly instead of porting
 * argparse's positional pattern matcher.
 */

import { SystemExit, ValueError, PythonError } from '../python/errors.mjs';
import { reprString } from '../python/repr.mjs';
import { writeStdout, writeStderr } from '../runtime/io.mjs';
import { HelpFormatter } from './formatter.mjs';
import { Action, StoreAction, HelpAction } from './actions.mjs';

/**
 * argparse's _negative_number_matcher. Python's `\d` is Unicode-aware for str
 * patterns, so `-٥` counts as a negative number here just as it does there.
 */
const NEGATIVE_NUMBER_RE = /^-\p{Nd}+$|^-\p{Nd}*\.\p{Nd}+$/u;

/** Raised by value conversion; the parser turns it into an error() call. */
class ArgumentError extends PythonError {
  constructor(action, message) {
    super('ArgumentError', message);
    this.action = action;
  }

  toString() {
    const name = this.action === null ? null : this.action.actionName();
    return name === null ? this.message : `argument ${name}: ${this.message}`;
  }
}

export class ArgumentParser {
  constructor({ prog, prefixChars = '-', allowAbbrev = true } = {}) {
    this.prog = prog;
    this.prefixChars = prefixChars;
    this.allowAbbrev = allowAbbrev;
    /** @type {Action[]} in declaration order — which is the order errors use. */
    this.actions = [];
    this.optionStringActions = new Map();
    this.addArgument(['-h', '--help'], {
      action: 'help',
      help: 'show this help message and exit',
    });
  }

  /**
   * @param {string[]} optionStrings e.g. ['--a']
   * @param {{action?: string, type?: Function, typeName?: string,
   *          required?: boolean, help?: string, metavar?: string}} options
   */
  addArgument(optionStrings, options = {}) {
    const dest = options.dest ?? deriveDest(optionStrings, this.prefixChars);
    const action =
      options.action === 'help'
        ? new HelpAction({ optionStrings, dest: 'help', help: options.help ?? null })
        : new StoreAction({
            optionStrings,
            dest,
            type: options.type ?? null,
            typeName: options.typeName ?? null,
            required: options.required ?? false,
            help: options.help ?? null,
            metavar: options.metavar ?? null,
          });
    this.actions.push(action);
    for (const optionString of optionStrings) {
      this.optionStringActions.set(optionString, action);
    }
    return action;
  }

  // --- help / usage -------------------------------------------------------

  formatter() {
    return new HelpFormatter(this.prog);
  }

  formatUsage() {
    return HelpFormatter.finish(this.formatter().formatUsage(this.actions));
  }

  formatHelp() {
    const formatter = this.formatter();
    const maxLength = formatter.actionMaxLength(this.actions);
    let text = formatter.formatUsage(this.actions);
    text += '\n';
    text += 'options:\n';
    for (const action of this.actions) {
      text += formatter.formatAction(action, maxLength);
    }
    text += '\n';
    return HelpFormatter.finish(text);
  }

  printHelp() {
    writeStdout(this.formatHelp());
  }

  printUsage(write = writeStderr) {
    write(this.formatUsage());
  }

  /** Usage block on stderr, then `prog: error: message`, then exit status 2. */
  error(message) {
    this.printUsage(writeStderr);
    this.exit(2, `${this.prog}: error: ${message}\n`);
  }

  exit(status = 0, message = null) {
    if (message) writeStderr(message);
    throw new SystemExit(status);
  }

  // --- parsing -----------------------------------------------------------

  parseArgs(argv) {
    const [namespace, extras] = this.parseKnownArgs(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  parseKnownArgs(argv) {
    const namespace = Object.create(null);
    for (const action of this.actions) {
      if (action instanceof StoreAction) namespace[action.dest] = action.defaultValue;
    }
    const extras = [];
    const seen = new Set();

    try {
      let index = 0;
      let afterSeparator = false;
      while (index < argv.length) {
        const token = argv[index];
        // Everything from the first `--` onwards is positional, and the `--`
        // itself survives into the leftovers because no positional consumes it.
        if (afterSeparator || token === '--') {
          if (token === '--') afterSeparator = true;
          extras.push(token);
          index += 1;
          continue;
        }
        const parsed = this.parseOptional(token);
        if (parsed === null) {
          extras.push(token);
          index += 1;
          continue;
        }
        index = this.consumeOptional(parsed, argv, index, namespace, extras, seen);
      }
    } catch (error) {
      if (error instanceof ArgumentError) this.error(error.toString());
      throw error;
    }

    const missing = this.actions.filter(
      (action) => action.required && !seen.has(action),
    );
    if (missing.length > 0) {
      this.error(
        `the following arguments are required: ${missing
          .map((action) => action.actionName())
          .join(', ')}`,
      );
    }
    return [namespace, extras];
  }

  /**
   * argparse's _parse_optional.
   * @returns {null | [Action | null, string, string | null]}
   *   null when the token is positional; the action is null when the token
   *   looks like an option but matches nothing.
   */
  parseOptional(argString) {
    if (argString === '') return null;
    if (!this.prefixChars.includes(argString[0])) return null;
    if (this.optionStringActions.has(argString)) {
      return [this.optionStringActions.get(argString), argString, null];
    }
    if (argString.length === 1) return null;
    if (argString.includes('=')) {
      const separator = argString.indexOf('=');
      const optionString = argString.slice(0, separator);
      if (this.optionStringActions.has(optionString)) {
        return [
          this.optionStringActions.get(optionString),
          optionString,
          argString.slice(separator + 1),
        ];
      }
    }

    const optionTuples = this.getOptionTuples(argString);
    if (optionTuples.length > 1) {
      const matches = optionTuples.map(([, optionString]) => optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${matches}`);
    } else if (optionTuples.length === 1) {
      return optionTuples[0];
    }

    if (NEGATIVE_NUMBER_RE.test(argString) && !this.hasNegativeNumberOptionals()) {
      return null;
    }
    if (argString.includes(' ')) return null;
    return [null, argString, null];
  }

  /** Abbreviation and concatenated-short-option candidates. */
  getOptionTuples(optionString) {
    const result = [];
    const chars = this.prefixChars;
    if (optionString.length > 1 && chars.includes(optionString[1])) {
      if (!this.allowAbbrev) return result;
      let prefix = optionString;
      let explicitArg = null;
      const separator = optionString.indexOf('=');
      if (separator >= 0) {
        prefix = optionString.slice(0, separator);
        explicitArg = optionString.slice(separator + 1);
      }
      for (const [candidate, action] of this.optionStringActions) {
        if (candidate.startsWith(prefix)) result.push([action, candidate, explicitArg]);
      }
      return result;
    }

    // Single-dash token: it may be a short option with its value attached.
    const shortPrefix = optionString.slice(0, 2);
    const shortExplicitArg = optionString.slice(2);
    const longExplicitArg = optionString.slice(1);
    for (const [candidate, action] of this.optionStringActions) {
      if (candidate === shortPrefix) {
        result.push([action, candidate, shortExplicitArg === '' ? null : shortExplicitArg]);
      } else if (candidate.startsWith(optionString)) {
        result.push([action, candidate, longExplicitArg]);
      }
    }
    return result;
  }

  hasNegativeNumberOptionals() {
    for (const optionString of this.optionStringActions.keys()) {
      if (NEGATIVE_NUMBER_RE.test(optionString)) return true;
    }
    return false;
  }

  /**
   * argparse's consume_optional, including the loop that peels concatenated
   * short options apart (`-h5` fires `-h` and leaves `-5` as a leftover).
   * @returns {number} index of the first unconsumed token
   */
  consumeOptional(parsed, argv, startIndex, namespace, extras, seen) {
    let [action, optionString, explicitArg] = parsed;
    const actionTuples = [];
    let stop;

    for (;;) {
      if (action === null) {
        extras.push(argv[startIndex]);
        return startIndex + 1;
      }

      if (explicitArg !== null) {
        const argCount = action.nargs === 0 ? 0 : 1;
        if (argCount === 0 && !this.prefixChars.includes(optionString[1]) && explicitArg !== '') {
          actionTuples.push([action, [], optionString]);
          const char = optionString[0];
          const nextOptionString = char + explicitArg[0];
          const nextExplicitArg = explicitArg.slice(1) === '' ? null : explicitArg.slice(1);
          if (this.optionStringActions.has(nextOptionString)) {
            action = this.optionStringActions.get(nextOptionString);
            optionString = nextOptionString;
            explicitArg = nextExplicitArg;
            continue;
          }
          extras.push(char + explicitArg);
          stop = startIndex + 1;
          break;
        }
        if (argCount === 1) {
          actionTuples.push([action, [explicitArg], optionString]);
          stop = startIndex + 1;
          break;
        }
        throw new ArgumentError(
          action,
          `ignored explicit argument ${reprString(explicitArg)}`,
        );
      }

      const start = startIndex + 1;
      const argCount = this.matchArgument(action, argv, start);
      actionTuples.push([action, argv.slice(start, start + argCount), optionString]);
      stop = start + argCount;
      break;
    }

    for (const [act, values, optString] of actionTuples) {
      seen.add(act);
      this.takeAction(act, values, optString, namespace);
    }
    return stop;
  }

  /**
   * How many following tokens this action consumes. For an optional, argparse
   * strips the `-` wildcards out of the nargs pattern, so a `--` marker can
   * never stand in for a value.
   */
  matchArgument(action, argv, start) {
    if (action.nargs === 0) return 0;
    const token = argv[start];
    if (token === undefined || token === '--' || this.parseOptional(token) !== null) {
      throw new ArgumentError(action, 'expected one argument');
    }
    return 1;
  }

