/**
 * The slice of argparse.ArgumentParser this program exercises: long options
 * with a single value, `-h/--help`, `required=True`, `type=` conversion, option
 * abbreviation, and the four error templates.
 *
 * The parser the original builds declares no positional arguments, so any token
 * that is not an option or an option's value is a leftover and ends up in the
 * "unrecognized arguments" list. That is modelled directly instead of porting
 * argparse's positional pattern matcher.
 */

import { SystemExit, ValueError, PythonError } from '../python/errors.mjs';
import { reprString } from '../python/repr.mjs';
import { writeStdout, writeStderr } from '../runtime/io.mjs';
import { HelpFormatter } from './formatter.mjs';
import { Action, StoreAction, HelpAction } from './actions.mjs';

/**
 * argparse's _negative_number_matcher. Python's `\d` is Unicode-aware for str
 * patterns, so `-٥` counts as a negative number here just as it does there.
 */
const NEGATIVE_NUMBER_RE = /^-\p{Nd}+$|^-\p{Nd}*\.\p{Nd}+$/u;

/** Raised by value conversion; the parser turns it into an error() call. */
class ArgumentError extends PythonError {
  constructor(action, message) {
    super('ArgumentError', message);
    this.action = action;
  }

  toString() {
    const name = this.action === null ? null : this.action.actionName();
    return name === null ? this.message : `argument ${name}: ${this.message}`;
  }
}

