/**
 * schedule.Job.
 *
 * The unit selectors are properties that mutate and return the job, mirroring
 * the library's chained DSL (`every(5).seconds.do(...)`).
 *
 * The line-number constants are the frames the frozen build reports, and they
 * are load-bearing: each of the three ways _schedule_next_run() can raise shows
 * up at a different line, which is how the failure regimes are told apart from
 * the outside.
 */

import { TimeDelta, DateTime, advanceUntilAfter } from '../python/datetime.mjs';
import { pyFrame } from '../python/frames.mjs';
import { partial, updateWrapper } from '../python/functools.mjs';
import { reprTuple, reprDict, reprValue } from '../python/repr.mjs';
import { ScheduleValueError } from '../python/errors.mjs';

export const SCHEDULE_MODULE = 'schedule/__init__.py';
/** Job.do() — the frame that calls _schedule_next_run(). */
export const LINE_DO = 657;
/** `self.period = datetime.timedelta(**{self.unit: interval})` */
export const LINE_PERIOD = 729;
/** `self.next_run = now + self.period` */
export const LINE_FIRST_NEXT_RUN = 731;
/** `self.next_run += self.period` inside `while self.next_run <= now:` */
export const LINE_ADVANCE_LOOP = 734;

const WEEKDAYS = [
  'monday',
  'tuesday',
  'wednesday',
  'thursday',
  'friday',
  'saturday',
  'sunday',
];

const VALID_UNITS = ['seconds', 'minutes', 'hours', 'days', 'weeks'];

export class Job {
  /**
   * @param {bigint} interval
   * @param {import('./scheduler.mjs').Scheduler | null} scheduler
   */
  constructor(interval, scheduler = null) {
    this.interval = interval;
    this.latest = null;
    this.jobFunc = null;
    this.unit = null;
    this.atTime = null;
    this.lastRun = null;
    this.nextRun = null;
    this.period = null;
    this.startDay = null;
    this.cancelAfter = null;
    this.tags = new Set();
    this.scheduler = scheduler;
  }

  get seconds() {
    this.unit = 'seconds';
    return this;
  }

  get minutes() {
    this.unit = 'minutes';
    return this;
  }

  get hours() {
    this.unit = 'hours';
    return this;
  }

  get days() {
    this.unit = 'days';
    return this;
  }

  get weeks() {
    this.unit = 'weeks';
    return this;
  }

  get second() {
    this.#requireUnitInterval('second');
    return this.seconds;
  }

  get minute() {
    this.#requireUnitInterval('minute');
    return this.minutes;
  }

  get hour() {
    this.#requireUnitInterval('hour');
    return this.hours;
  }

  get day() {
    this.#requireUnitInterval('day');
    return this.days;
  }

  get week() {
    this.#requireUnitInterval('week');
    return this.weeks;
  }

  get monday() {
    return this.#startOnWeekday('monday');
  }

  get tuesday() {
    return this.#startOnWeekday('tuesday');
  }

  get wednesday() {
    return this.#startOnWeekday('wednesday');
  }

  get thursday() {
    return this.#startOnWeekday('thursday');
  }

  get friday() {
    return this.#startOnWeekday('friday');
  }

  get saturday() {
    return this.#startOnWeekday('saturday');
  }

  get sunday() {
    return this.#startOnWeekday('sunday');
  }

