    return (
      `Job(interval=${this.interval}, unit=${this.unit}, do=${name}, ` +
      `args=${reprTuple(args)}, kwargs=${reprDict(kwargs)})`
    );
  }

  toString() {
    return this.__str__();
  }

  #requireUnitInterval(name) {
    // Unreachable from this program — every singular accessor it uses is on a
    // job built by every() with the default interval of 1 — so the exact
    // CPython message is not observable from the outside.
    if (this.interval !== 1n) {
