  }

  #scheduleNextRun() {
    if (!VALID_UNITS.includes(this.unit)) {
      throw new ScheduleValueError(
        'Invalid unit (valid units are `seconds`, `minutes`, `hours`, ' +
          '`days`, and `weeks`)',
