    // datetime back past year 1 and raises — both faithful to the original.
    this.nextRun = pyFrame(
      SCHEDULE_MODULE,
      LINE_ADVANCE_LOOP,
      '_schedule_next_run',
      () => advanceUntilAfter(this.nextRun, now, this.period),
    );
  }
}

