        TimeDelta.fromDays(daysAhead).subtract(this.period),
      );
    }

    // A zero interval never leaves this loop, and a negative one walks the
    // datetime back past year 1 and raises — both faithful to the original.
    this.nextRun = pyFrame(
      SCHEDULE_MODULE,
      LINE_ADVANCE_LOOP,
      '_schedule_next_run',
      () => advanceUntilAfter(this.nextRun, now, this.period),
    );
  }
}

