/**
 * schedule.Scheduler — the job registry behind the module-level helpers.
 */

import { Job } from './job.mjs';

export class Scheduler {
  constructor() {
    /** @type {Job[]} */
    this.jobs = [];
  }

  /** every() defaults to an interval of 1. */
  every(interval = 1n) {
    return new Job(interval, this);
  }

  /** get_jobs() hands back a copy, optionally filtered by tag. */
  getJobs(tag = null) {
    if (tag === null) return [...this.jobs];
    return this.jobs.filter((job) => job.tags.has(tag));
  }

  clear(tag = null) {
    if (tag === null) this.jobs = [];
    else this.jobs = this.jobs.filter((job) => !job.tags.has(tag));
  }

  cancelJob(job) {
    const index = this.jobs.indexOf(job);
    if (index >= 0) this.jobs.splice(index, 1);
  }
}

